local a=DonationScriptDirectory.."\\event"local function b(c)local d=tostring(c)local e=d:reverse():gsub("(%d%d%d)","%1,"):reverse()return e:gsub("^,","")end;function findDonationTier(c)for f,g in ipairs(DonationConfig.donationTiers or{})do local h=tonumber(g.amount)if h~=nil and h==c then return g end end;return nil end;local function i(j)if type(j)~="string"or not j:match("^[%w_-]+$")then return nil,"이벤트 파일명이 올바르지 않습니다."end;local k,l=loadfile(a.."\\"..j..".lua")if k==nil then return nil,"이벤트 파일을 불러올 수 없습니다: "..tostring(l)end;local m,n=xpcall(k,debug.traceback)if not m then return nil,"이벤트 파일 초기화에 실패했습니다: "..tostring(n)end;if type(n)~="function"then return nil,"이벤트 파일은 실행 함수를 반환해야 합니다: "..j end;return n,nil end;function runDonationEvent(o,p,c)local g=findDonationTier(c)if g==nil then return false,nil,"설정된 후원 등급이 없습니다."end;local q,l=i(g.event)if q==nil then return false,g,l end;local r={playerUid=o,playerName=p,amount=c,formattedAmount=b(c),tier=g,sendSystemToPlayer=sendSystemToPlayer,log=log}local s,t,u=xpcall(function()return q(r)end,debug.traceback)if not s then return false,g,"이벤트 실행 중 오류가 발생했습니다: "..tostring(t)end;if t==false then return false,g,tostring(u or"이벤트가 실패했습니다.")end;return true,g,u end